import type { ReactNode } from "react";
import { Box, Link, Typography } from "@mui/material";
import type { SxProps, Theme } from "@mui/material/styles";

export type BlocksTextNode = {
  type?: string;
  text?: string;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  strikethrough?: boolean;
  code?: boolean;
  url?: string;
  format?: "ordered" | "unordered";
  level?: number;
  children?: BlocksTextNode[];
};

type BlocksTextProps = {
  content?: BlocksTextNode[] | string | null;
  sx?: SxProps<Theme>;
};

function renderInline(nodes: BlocksTextNode[] = [], keyPrefix = "inline") {
  return nodes.map((node, index) => {
    const key = `${keyPrefix}-${index}`;
    if (node.type === "link" && node.url) {
      return (
        <Link key={key} href={node.url} target="_blank" rel="noopener noreferrer">
          {renderInline(node.children || [], key)}
        </Link>
      );
    }

    let text: ReactNode = node.text || "";
    if (node.bold) text = <strong>{text}</strong>;
    if (node.italic) text = <em>{text}</em>;
    if (node.underline) text = <u>{text}</u>;
    if (node.strikethrough) text = <s>{text}</s>;
    if (node.code) text = <code>{text}</code>;
    return <Box key={key} component="span">{text}</Box>;
  });
}

export default function BlocksText({ content, sx }: BlocksTextProps) {
  if (!content) return null;
  if (typeof content === "string") {
    return (
      <Typography sx={{ whiteSpace: "pre-line", ...sx }}>{content}</Typography>
    );
  }

  return (
    <Box sx={sx}>
      {content.map((block, index) => {
        const key = `block-${index}`;
        if (block.type === "list") {
          const ListTag = block.format === "ordered" ? "ol" : "ul";
          return (
            <Box key={key} component={ListTag} sx={{ pl: 3, m: 0, mb: 1.5 }}>
              {(block.children || []).map((item, itemIndex) => (
                <Box key={`${key}-item-${itemIndex}`} component="li" sx={{ mb: 0.5 }}>
                  {renderInline(item.children || [], `${key}-${itemIndex}`)}
                </Box>
              ))}
            </Box>
          );
        }

        if (block.type === "quote") {
          return (
            <Box
              key={key}
              component="blockquote"
              sx={{
                m: 0,
                mb: 1.5,
                pl: 2,
                borderLeft: "3px solid currentColor",
                opacity: 0.9,
              }}
            >
              {renderInline(block.children || [], key)}
            </Box>
          );
        }

        if (block.type === "heading") {
          const variant = block.level === 1 ? "h3" : block.level === 2 ? "h4" : "h5";
          return (
            <Typography key={key} variant={variant} sx={{ fontWeight: 600, mb: 1 }}>
              {renderInline(block.children || [], key)}
            </Typography>
          );
        }

        return (
          <Typography key={key} component="p" sx={{ mb: 1.5 }}>
            {renderInline(block.children || [], key)}
          </Typography>
        );
      })}
    </Box>
  );
}
